  "new_content": "class TokenPatternOperator(str):
    \"\"\"Validator for token pattern operators, including min/max quantifiers.\"\"\"

    @classmethod
    def __get_validators__(cls):
        yield cls.validate

    @classmethod
    def validate(cls, v):
        if not isinstance(v, str):
            raise TypeError('string required')
        # Simple operators
        if v in ('+', '*', '?', '!'):
            return v
        # Min/max quantifier operators: {n}, {n,m}, {n,}, {,m}
        if v.startswith('{') and v.endswith('}'):
            inner = v[1:-1]
            # Split by comma
            parts = inner.split(',')
            if len(parts) == 1:
                # {n} format
                if parts[0].isdigit():
                    return v
            elif len(parts) == 2:
                # {n,m}, {n,}, {,m} formats
                left, right = parts
                # Check {n,m}
                if left.isdigit() and right.isdigit():
                    return v
                # Check {n,}
                if left.isdigit() and right == '':
                    return v
                # Check {,m}
                if left == '' and right.isdigit():
                    return v
        raise ValueError(f'Invalid operator: {v}')"
}
